def largest_rect(h):
    st, best = [], 0
    for i in range(len(h) + 1):
        cur = h[i] if i < len(h) else 0       # sentinel flush
        while st and h[st[-1]] >= cur:
            ht = h[st.pop()]
            left = st[-1] if st else -1
            best = max(best, ht * (i - left - 1))
        st.append(i)
    return best

