int longestValidParentheses(string s){
    stack<int> st; st.push(-1);           // BASE anchor
    int best = 0;
    for (int i = 0; i < s.size(); i++) {
        if (s[i]=='(' ) st.push(i);
        else {
            st.pop();                     // consume a matcher (or base)
            if (st.empty()) st.push(i);   // new barrier: unmatched closer
            else best = max(best, i - st.top());
        }
    }
    return best;
}

