def longest_valid_parentheses(s):
    st, best = [-1], 0
    for i, c in enumerate(s):
        if c == '(': st.append(i)
        else:
            st.pop()
            if not st: st.append(i)       # new barrier
            else: best = max(best, i - st[-1])
    return best
